cd /workspace && python3 - <<'PY'
import json,subprocess,sys
MAIN='submission/main.py'
def run(doc):
    p=subprocess.run([sys.executable,'-I','-B',MAIN],input=json.dumps(doc).encode(),capture_output=True)
    return p.returncode,json.loads(p.stdout) if p.returncode==0 else None
def msg(start,headers,body=b''):
    return (('\r\n'.join([start]+headers)+'\r\n\r\n').encode()+body).hex()
def cfg(ttl=10,cap=10):
    return {"accounts":[{"id":"alice","default":"sip:alice@lab.test","aliases":["sip:alice@lab.test"]}],"peers":[{"id":"e","mode":"access","accounts":[]}],"ttl_ms":ttl,"capacity":cap}
def w(callid='c',body=b''):
    return msg('MESSAGE sip:bob@lab.test SIP/2.0',['From: sip:alice@lab.test;tag=t','To: <sip:bob@lab.test>','Call-ID: '+callid,'CSeq: 1 MESSAGE','Content-Length: '+str(len(body))],body)
def ev(t,wh): return {"t":t,"peer":"e","auth":"alice","egress":"internal","wire_hex":wh}
def show(n,doc):
    rc,j=run(doc); print(n,rc,[ (r['index'],r['decision'],r.get('first'),r.get('reason')) for r in j['results']], {k:j[k] for k in ('accepted','replayed','rejected','live')})

show('ttl boundary',{"version":1,"config":cfg(ttl=10,cap=10),"events":[ev(0,w()),ev(9,w()),ev(10,w())]})
show('cap1 evict then readd',{"version":1,"config":cfg(ttl=1000,cap=1),"events":[ev(0,w('A')),ev(1,w('B')),ev(2,w('A'))]})
# malformed event triggers expiry
doc={"version":1,"config":cfg(ttl=5,cap=10),"events":[ev(0,w('A')),{"t":5,"peer":"e","auth":"alice","egress":"internal","wire_hex":"zz"},ev(6,w('A'))]}
show('malformed expiry',doc)
# replay should not refresh: accept t0, replay t4, then t6 -> expired at 5? 
show('replay no refresh',{"version":1,"config":cfg(ttl=5,cap=10),"events":[ev(0,w('A')),ev(4,w('A')),ev(5,w('A'))]})
